        // Contractor_placement.php L337-389 → adjustPlacementStartDate
        app.MapPost("/api/v1/contractor/placement/adjust-start-date", async (int placement_id, string start_date, ContractorPlacementRepository repo, ILogger logger) =>
        {
            // Model/Contractor_placement.php L340-342 → validate inputs
            if (placement_id == 0 || start_date == "2001-01-01")
                return Results.BadRequest();

            // Model/Contractor_placement.php L344 → load placement
            var plcObj = await repo.GetByIdAsync(placement_id);
            if (plcObj == null || !plcObj.IsPopulated())
                return Results.NotFound();

            // Model/Contractor_placement.php L347-349 → update start date
            plcObj.StartDate = start_date;
            if (plcObj.HasChanged())
            {
                await repo.SaveAsync(plcObj);
                ContractorPlacementOverdueStatusMap.DeleteInvalidEntries(plcObj.Id);

                // Model/Contractor_placement.php L352-369 → update profiles
                foreach (var profile in plcObj.AllProfiles())
                {
                    if (profile.ValidFrom <= profile.ValidTo)
                    {
                        plcObj.StartDate = DateSanitize(plcObj.StartDate);
                        if (plcObj.StartDate < profile.ValidFrom)
                        {
                            profile.ValidFrom = plcObj.StartDate;
                            await repo.SaveProfileAsync(profile);
                            Profile.VoidAfterProfile(plcObj.Id, profile.ValidFrom);
                            break;
                        }
                        if (plcObj.StartDate >= profile.ValidFrom && plcObj.StartDate <= profile.ValidTo)
                        {
                            profile.ValidFrom = plcObj.StartDate;
                            await repo.SaveProfileAsync(profile);
                            Profile.VoidAfterProfile(plcObj.Id, profile.ValidFrom);
                            break;
                        }
                        profile.AdjustBurdenNew(plcObj.IsPassthru);
                        await repo.SaveProfileAsync(profile);
                    }
                }

                // Model/Contractor_placement.php L373-385 → H1B Employees Credit Exception
                var visaTypes = TrimAll(GetConfig("100 percentage credit work authorization list", "H1B,CPT,OPT EAD,TN"), true, ',', false);
                var demographicId = ContractorPlacement.CheckDemographicReverseMap(placement_id);
                var demographicObj = new OnbDemographic(demographicId);
                var visaType = demographicObj.GetVisaType();
                var cutoffDate = DateToDate(GetConfig("100 percentage credit cutoff date", "2023-10-06"));

                if (visaTypes.Contains(visaType))
                {
                    foreach (var profile in plcObj.AllProfiles())
                    {
                        if (profile.ValidFrom >= cutoffDate)
                        {
                            Profile.UpdateH1bEmployeesApplyPct(profile.Id);
                        }
                    }
                }
            }

            return Results.Ok();
        });

