        app.MapGet("/api/v1/contractor/best-match", async (string custids, string contractorname, string tsweek, [FromServices] IDbConnection dbConnection) =>
        {
            var list = new List<dynamic>();
            var custIdsArray = QuoteAndTransform(custids);
            var contractorsArray = QuoteAndTransform(await Contractor.BestMatchAsync(contractorname));

            if (custIdsArray.Count < 1 || contractorsArray.Count < 1)
            {
                return Results.Json(list);
            }

            var query = @"SELECT cp.id AS id,
                                cp.start_date AS start_date,
                                cp.deactivation_date AS deactivation_date,
                                cp.is_active AS is_active,
                                c.id AS contractor_id,
                                c.firstname AS firstname,
                                c.mi AS mi,
                                c.lastname AS lastname,
                                c.is_active AS is_active_contractor
                           FROM contractor_placement cp
                           JOIN contractor c ON cp.contractor_id = c.id
                          WHERE cp.customer_id IN @CustIds
                            AND c.id IN @Contractors";

            list = (await dbConnection.QueryAsync(query, new { CustIds = custIdsArray, Contractors = contractorsArray })).ToList();

            if (list.Count < 1)
            {
                query = @"SELECT cp.id AS id,
                                cp.start_date AS start_date,
                                cp.deactivation_date AS deactivation_date,
                                cp.is_active AS is_active,
                                c.id AS contractor_id,
                                c.firstname AS firstname,
                                c.mi AS mi,
                                c.lastname AS lastname,
                                c.is_active AS is_active_contractor
                           FROM contractor_placement cp
                           JOIN contractor c ON cp.contractor_id = c.id
                          WHERE c.id IN @Contractors";

                list = (await dbConnection.QueryAsync(query, new { Contractors = contractorsArray })).ToList();
            }

            if (list.Count > 1)
            {
                var tsSecs = DateTimeOffset.Parse(tsweek).ToUnixTimeSeconds();
                var maxDeviation = 7 * 86400;

                list = list.Where(entry =>
                {
                    var startDate = DateTimeOffset.Parse(entry.start_date.ToString()).ToUnixTimeSeconds();
                    var deactivationDate = entry.deactivation_date.ToString() != "2000-01-01 00:00:00"
                        ? DateTimeOffset.Parse(entry.deactivation_date.ToString()).ToUnixTimeSeconds()
                        : (long?)null;

                    return ContractorPlacement.IsPerm(entry.id) ||
                           (tsSecs - startDate >= -maxDeviation &&
                            (deactivationDate == null || tsSecs - deactivationDate <= maxDeviation));
                }).ToList();
            }

            return Results.Json(list);
        });

