        {
            if (old_id == 0 || new_id == 0)
            {
                return Results.BadRequest(new { error = "Invalid job ID(s) provided." });
            }

            var updated = 0;
            var placements = await repo.SearchAsync(new { jobreq_id = old_id, is_active = "Y" });

            foreach (var plc in placements)
            {
                plc.JobreqId = new_id;
                await repo.UpdateAsync(plc);
                updated++;
            }

            return Results.Ok(new { updated });
