    private static List<string> TrimAll(string input, bool trim, char separator, bool removeEmpty)
    {
        var parts = input.Split(separator);
        var result = new List<string>();
        foreach (var part in parts)
        {
            var trimmed = trim ? part.Trim() : part;
            if (!removeEmpty || !string.IsNullOrEmpty(trimmed))
            {
                result.Add(trimmed);
            }
        }
        return result;
    }

