    public class ContractorPlacement
    {
        public int ContractorId { get; }
        public int JobreqId { get; }
        private bool populated;

        public ContractorPlacement(int id, IDbConnection dbConnection)
        {
            var result = dbConnection.QueryFirstOrDefault("SELECT contractor_id, jobreq_id FROM contractor_placement WHERE id = @Id", new { Id = id });
            if (result != null)
            {
                ContractorId = result.contractor_id;
                JobreqId = result.jobreq_id;
                populated = true;
            }
        }

        public bool IsPopulated() => populated;
    }

